from collections import deque

def min_lexicographical_string(s):
    t = deque()
    u = []

    for char in s:
        t.append(char)

    while t:
        if not u or t[0] <= u[-1]:
            u.append(t.popleft())
        else:
            u.appendleft(t.pop())

    return ''.join(u)

