def min_lexicographical_string(s):
    n = len(s)
    stack = []
    u = []

    for i in range(n):
        if not stack or s[i] >= stack[-1]:
            stack.append(s[i])
        else:
            while stack and s[i] < stack[-1]:
                u.append(stack.pop())
            stack.append(s[i])

    while stack:
        u.append(stack.pop())

    return ''.join(u)

