from collections import deque

def min_lexicographical_string(s):
    t = deque()
    u = deque()

    for char in s:
        t.append(char)

    while t:
        if not u or t[-1] <= u[0]:
            u.appendleft(t.pop())
        else:
            u.append(t.popleft())

    return ''.join(u)

# Example usage:
if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()
    s = data[0]
    result = min_lexicographical_string(s)
    print(result)
